package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

// worker 模拟一个分步执行的耗时任务，随时监听 ctx 的取消信号
func worker(ctx context.Context, id int, wg *sync.WaitGroup) {
	defer wg.Done() // 任务结束（无论正常与否）都要通知 WaitGroup
	for i := 0; i < 5; i++ {
		select {
		case <-ctx.Done(): // 收到取消/超时信号，立即退出
			fmt.Printf("worker %d 被取消: %v\n", id, ctx.Err())
			return
		case <-time.After(200 * time.Millisecond): // 模拟每一步的耗时
			fmt.Printf("worker %d 完成第 %d 步\n", id, i+1)
		}
	}
}

// fetchWithTimeout 演示给下游调用加超时的"教科书写法"
func fetchWithTimeout(ctx context.Context, url string) (string, error) {
	// 1. 派生一个 300ms 超时的子 context
	ctx, cancel := context.WithTimeout(ctx, 300*time.Millisecond)
	defer cancel() // 关键：无论走哪个分支，都必须释放资源

	type result struct {
		data string
		err  error
	}
	ch := make(chan result, 1) // 带缓冲，避免 goroutine 泄漏

	// 2. 后台发起一个"慢请求"
	go func() {
		time.Sleep(1 * time.Second) // 模拟耗时 1s 的网络调用
		ch <- result{data: "response from " + url}
	}()

	// 3. select 同时监听结果与超时
	select {
	case <-ctx.Done():
		// 用 %w 包装错误，保留错误链，方便上层 errors.Is 判断
		return "", fmt.Errorf("请求 %s 失败: %w", url, ctx.Err())
	case r := <-ch:
		return r.data, r.err
	}
}

func main() {
	// ===== 场景一：WithCancel 手动取消多个 worker =====
	var wg sync.WaitGroup
	ctx, cancel := context.WithCancel(context.Background())
	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go worker(ctx, i, &wg)
	}
	time.Sleep(500 * time.Millisecond)
	fmt.Println("--- 主流程发出取消信号 ---")
	cancel() // 通知所有子任务停止
	wg.Wait()

	// ===== 场景二：WithTimeout 控制下游调用 =====
	resp, err := fetchWithTimeout(context.Background(), "https://api.example.com")
	if err != nil {
		// 精确判断错误类型：超时 还是 被取消
		if errors.Is(err, context.DeadlineExceeded) {
			fmt.Println("[监控告警] 下游接口超时，触发降级逻辑")
		}
		fmt.Println("fetch 错误:", err)
		return
	}
	fmt.Println("fetch 成功:", resp)
}

