package main

import (
    "context"
    "fmt"
    "time"
)

func main() {
    ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
    defer cancel()

    ch := make(chan string, 1)
    go func() {
        time.Sleep(200 * time.Millisecond)
        ch <- "done"
    }()

    select {
    case v := <-ch:
        fmt.Println("got:", v)
    case <-ctx.Done():
        fmt.Println("timeout:", ctx.Err())
    }
}
